CREATE TABLE IF NOT EXISTS sources (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_key VARCHAR(120) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, source_url TEXT NOT NULL, source_type VARCHAR(40) NOT NULL DEFAULT 'public', trust_score DECIMAL(5,2), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS locations (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, region VARCHAR(120) NOT NULL, latitude_approx DECIMAL(8,5), longitude_approx DECIMAL(8,5), coordinate_precision_m INT UNSIGNED, is_sensitive TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_locations_region(region)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ingest_runs (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, adapter_key VARCHAR(120) NOT NULL, started_at DATETIME(3) NOT NULL, finished_at DATETIME(3), status VARCHAR(32) NOT NULL DEFAULT 'running', item_count INT UNSIGNED NOT NULL DEFAULT 0, error_message TEXT, KEY idx_ingest_started(started_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS observations (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_id BIGINT UNSIGNED NOT NULL, location_id BIGINT UNSIGNED, ingest_run_id BIGINT UNSIGNED, external_id VARCHAR(191), species_name VARCHAR(255) NOT NULL, observed_at DATETIME(3), published_at DATETIME(3), evidence_url TEXT, raw_payload JSON, evidence_state VARCHAR(32) NOT NULL DEFAULT 'unverified', review_state VARCHAR(32) NOT NULL DEFAULT 'pending', observed_precision VARCHAR(32) NOT NULL DEFAULT 'region', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_source_external(source_id,external_id), KEY idx_review_state(review_state), CONSTRAINT fk_obs_source FOREIGN KEY(source_id) REFERENCES sources(id), CONSTRAINT fk_obs_location FOREIGN KEY(location_id) REFERENCES locations(id), CONSTRAINT fk_obs_ingest FOREIGN KEY(ingest_run_id) REFERENCES ingest_runs(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS media (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, observation_id BIGINT UNSIGNED NOT NULL, object_key VARCHAR(512) NOT NULL UNIQUE, content_sha256 CHAR(64), content_type VARCHAR(120), width INT UNSIGNED, height INT UNSIGNED, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_media_obs FOREIGN KEY(observation_id) REFERENCES observations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS review_queue (
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, observation_id BIGINT UNSIGNED NOT NULL, state VARCHAR(32) NOT NULL DEFAULT 'queued', priority TINYINT UNSIGNED NOT NULL DEFAULT 50, reviewer VARCHAR(191), decision_reason TEXT, queued_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_at TIMESTAMP NULL, KEY idx_review_state_priority(state,priority), CONSTRAINT fk_review_obs FOREIGN KEY(observation_id) REFERENCES observations(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
